    constructor(C _c) { c = _c; }

    // single public function: attempt to lock in a guess with a given hash and amount
    // params: the hash to lock, and amount of wei to send (must be 1 ether to succeed)
    function run(bytes32 h, uint amount) public payable {
        require(address(this).balance >= amount);

        // record balance of c before the call
        uint balBefore = address(c).balance;

        // read current stored Guess for this contract via the public getter
        // C.guesses is public so solidity generates a getter: guesses(address) -> (uint, bytes32)
        (uint beforeBlock, bytes32 beforeHash) = c.guesses(address(this));

        bool reverted;
        // perform the state-changing call at top-level
        try c.lockInGuess{value: amount}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        (uint afterBlock, bytes32 afterHash) = c.guesses(address(this));
        uint balAfter = address(c).balance;

        // General rule (single assert):
