        //   - amount must have been exactly 1 ether (since contract requires msg.value == 1 ether)
        //   - beforeBlock must have been 0 (no active guess allowed)
        //   - afterHash equals h and afterBlock equals current block number + 1 as stored
        // If call reverted then contract balance must be unchanged (no Ether accepted)
        assert(
            (!reverted && amount == 1 ether && beforeBlock == 0 && afterHash == h && afterBlock == block.number + 1)
            || (reverted && balAfter == balBefore)
        );
    }

    // receive to accept refunds if any
