contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: (1) try to set up a guess paying 1 ether to c, (2) advance nothing (we cannot change block.number here),
    // then call settle(). We capture whether settle reverted and balances before/after and observe c's public getter
    // for guesses(msg.sender) via the auto getter: guesses(address) returns (uint, bytes32) because the struct is public.
    // However in contract C the mapping is not declared public; since we can only observe via public surface, we instead
    // rely on observable effects: if settle pays out 2 ether, InvMutTest's balance increases by 2 ether and c's balance
    // decreases by 2 ether. We also check that after a non-reverting settle the contract's recorded block for this caller
    // is cleared by observing that a subsequent lockInGuess call with exactly 1 ether can succeed (i.e., not revert) only
    // if there was no active guess. Thus the rule ties payout to the fact that prior guess matched the answer and that
    // after payout the slot is cleared because lockInGuess succeeds.

    // Single public function as required. It is payable so we can send funds to c.
    function run(bytes32 h, uint lockAmount, uint settleCallDummy) public payable {
        // Preconditions only on available Ether for this test contract to send to c when calling lockInGuess.
        require(address(this).balance >= lockAmount + 1 wei);
        // We only use lockAmount (should be 1 ether to succeed) and ignore settleCallDummy (just an unconstrained input)

        uint balCTestBefore = address(c).balance;
        uint balThisBefore = address(this).balance;

        bool lockReverted;
        // Top-level state-changing call: try to lock in a guess with provided amount
        try c.lockInGuess{value: lockAmount}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Now attempt settle; it may revert. Capture whether it reverted and balances after.
        bool settleReverted;
        uint balCTestMid = address(c).balance;
        uint balThisMid = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint balCTestAfter = address(c).balance;
        uint balThisAfter = address(this).balance;

        // Now attempt to call lockInGuess again with exactly 1 ether to check whether the caller has an active guess slot.
        // If there was no active guess (either we never successfully locked one, or settle cleared it), this call should succeed.
        bool secondLockReverted;
        // ensure we have funds to attempt this second lock; require available balance
        require(address(this).balance >= 1 ether);
        try c.lockInGuess{value: 1 ether}(h) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }

        // General rule (single assert): If settle did not revert and InvMutTest's balance increased by exactly 2 ether
        // (meaning settle paid out 2 ether to the caller), then the initial lockInGuess must have succeeded (we had sent 1 ether),
        // and the subsequent attempt to lockInGuess must have succeeded as well (meaning the stored guess slot was cleared after payout).
        // Conversely, if settle reverted or did not pay out 2 ether, we make no claim.
        assert(
            ( !settleReverted && balThisAfter == balThisMid + 2 ether && !lockReverted && !secondLockReverted )
            || ( settleReverted || !(balThisAfter == balThisMid + 2 ether) )
        );
    }

    receive() external payable {}
}

