contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We will drive lockInGuess and settle. We observe via calls to the public mapping getter
    // (auto-generated) and contract balances. The test function is payable to supply ether for lockInGuess.
    function run(bytes32 hash, uint lockValue, bool doSettle) public payable {
        require(address(this).balance >= lockValue);
        // Precondition: lockValue should be 1 ether for a successful lockInGuess call
        // but we don't require it here — we will detect whether the call reverted.

        // Read c balance before any calls
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool lockReverted;
        // Attempt lockInGuess with provided value
        try c.lockInGuess{value: lockValue}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After calling lockInGuess (whether reverted or not) read the public getter for guesses[msg.sender]
        // The compiler-generated getter has signature guesses(address) returning (uint256,uint256 or bytes32?)
        // For a struct (uint,bytes32) the getter returns (uint256,bytes32) in that order.
        (uint recordedBlock, bytes32 recordedGuess) = c.guesses(address(this));

        // Optionally attempt settle if requested
        bool settleReverted = true;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule asserted:
        // 1) If lockInGuess succeeded (did not revert) then the stored guess equals the provided hash and recordedBlock != 0.
        // 2) If lockInGuess reverted then recordedBlock == 0 and recordedGuess == bytes32(0).
        // 3) If settle was attempted and did not revert then the recordedBlock must have been cleared to 0 (the contract resets it);
        //    additionally, the only way this tester's balance could increase is via a successful settle (transfer of 2 ether),
        //    so if settle succeeded then afterThis > beforeThis and afterC + (afterThis - beforeThis) == beforeC.
        assert(
            (
                (!lockReverted && recordedBlock != 0 && recordedGuess == hash)
                || (lockReverted && recordedBlock == 0 && recordedGuess == bytes32(0))
            )
            && (
                (!doSettle) || (doSettle && (settleReverted || (recordedBlock == 0 && afterThis > beforeThis && afterC + (afterThis - beforeThis) == beforeC)))
            )
        );
    }

    // Allow receiving ether when settle transfers funds
    receive() external payable {}
}

