    // uint pay - amount of wei to send to lockInGuess (should be 1 ether to succeed)
    // uint fakeBlockAdvance - a dummy parameter representing number of blocks to wait; we cannot actually advance blocks here,
    //                         but the property will quantify over the case where block.number > stored block number by calling settle once (the checker will model arbitrary block numbers).
    function run(bytes32 h, uint pay, uint /* fakeBlockAdvance */) public payable {
        // must have enough balance to send to c
        require(address(this).balance >= pay);

        bool lockedReverted;
        try c.lockInGuess{value: pay}(h) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Read observable: contract balance
        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        // Attempt to call settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint balAfter = address(this).balance;
        uint cBalAfter = address(c).balance;

        // General rule asserted:
        // If lockInGuess did not revert (we successfully locked by sending the required ETH),
        // then settle called afterwards (in some future block as assumed by the model) must not revert when block.number > locked block.
        // Because we cannot inspect the stored block from c, we assert a weaker but general observable rule:
        // - If lockInGuess succeeded (lockedReverted == false) AND settle did not revert, then the only possible balance change is that the test contract's balance increased by either 0 or 2 ether
        //   and c's balance decreased by the same amount. This captures that settle either paid out 2 ether on a correct guess or paid nothing, and did not send arbitrary amounts.

        assert(
            // either lock failed and nothing is required about balances / revert of settle,
            // or lock succeeded and then if settle didn't revert, balances differ only by 0 or exactly 2 ether transfer to this contract
            lockedReverted || (
                // if settle reverted after a successful lock, that's allowed by model (e.g., if called too early), so no further constraint
                settleReverted || (
                    // settle succeeded: delta must be 0 or +2 ether to this contract and c balance moved correspondingly
                    ( (balAfter == balBefore) && (cBalAfter == cBalBefore) ) ||
                    ( (balAfter == balBefore + 2 ether) && (cBalAfter + 2 ether == cBalBefore) )
