        // The mapping returns (uint, bytes32) because Guess struct has two fields.
        (uint256 lockedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Now attempt to call settle. It may revert if no guess was recorded or block conditions fail.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Balances after actions
        uint256 afterTester = address(this).balance;
        uint256 afterC = address(c).balance;

        // General rule to assert:
        // If lockInGuess reverted, the contract state must be unchanged for this caller (no block set)
        // and balances unchanged. If lockInGuess succeeded then lockedBlock != 0 and storedGuess == guessHash.
        // After attempting settle, the mapping entry for this caller must be cleared (block == 0).
        // Also, the tester's balance may only increase by at most 1 ether (winning pays 2 ether but cost was 1),
        // and the net effect on c's balance corresponds (conservation: total change opposite).

