            (
                lockReverted
                && lockedBlock == 0
                && storedGuess == bytes32(0)
                && afterTester == beforeTester
                && afterC == beforeC
            )
            ||
            // case B: lockInGuess succeeded -> mapping reflects the guess and a block was set
            (
                !lockReverted
                && lockedBlock != 0
                && storedGuess == guessHash
                // after settle, mapping entry for this caller must be cleared (block == 0)
                && (settleReverted || c.guesses(address(this)).block == 0)
                // balances: tester could either have lost 1 ether (if settle didn't pay back) or gained 1 ether net (if won)
                && (afterTester == beforeTester -  (sendAmount == 1 ether ? 1 ether : 0) // if lockInGuess consumed 1 ether
